style:
.btn {
    background-color: aquamarine;
    padding: 10px 20px;
    text-decoration: none;
    color: darkslategrey;
    font-weight: 600;
    border-radius: 6px;
}

#wrp-dash-root *{box-sizing:border-box;font-family:var(--font-stack,'Inter',sans-serif)}
#wrp-dash-root{--g:#22c55e;--r:#ef4444;--o:#f59e0b;--b:#3b82f6;--p:#7c3aed;--grey:#6b7280;padding:0 2px 24px}
.wrp-loading{padding:40px;text-align:center;color:var(--text-muted)}
.wrp-section-title{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--text-muted);margin:20px 0 8px}
.wrp-row{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:4px}
.wrp-scope{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:16px;padding:10px 14px;background:var(--card-bg,#fff);border:1px solid var(--border-color,#e5e7eb);border-radius:8px}
.wrp-scope label{font-size:12px;color:var(--text-muted);margin-bottom:0;margin-right:2px}
.wrp-scope select{font-size:12px;padding:3px 6px;border:1px solid var(--border-color);border-radius:4px;background:var(--bg-color,#fff);color:var(--text-color,#111);cursor:pointer}
.wrp-scope button{font-size:12px;padding:4px 12px;border:none;border-radius:4px;background:var(--primary,#4f46e5);color:#fff;cursor:pointer}
.wrp-card{flex:1;min-width:90px;padding:12px 14px;background:var(--card-bg,#fff);border:1px solid var(--border-color,#e5e7eb);border-radius:8px}
.wrp-card.clickable{cursor:pointer;transition:box-shadow .15s,transform .1s}
.wrp-card.clickable:hover{box-shadow:0 4px 12px rgba(0,0,0,.12);transform:translateY(-1px)}
.wrp-card-val{font-size:22px;font-weight:700;line-height:1.1}
.wrp-card-lbl{font-size:11px;color:var(--text-muted);margin-top:2px}
.wrp-card-sub{font-size:10px;color:var(--text-muted)}
.wrp-pipe-row{display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid var(--border-color,#f3f4f6)}
.wrp-pipe-row:last-child{border:none}
.wrp-pipe-lbl{min-width:120px;font-size:12px;color:var(--text-color)}
.wrp-pipe-bar{flex:1;height:10px;background:var(--border-color,#e5e7eb);border-radius:5px;overflow:hidden}
.wrp-pipe-fill{height:100%;border-radius:5px;transition:width .6s ease}
.wrp-pipe-cnt{min-width:50px;text-align:right;font-size:12px;font-weight:600}
.wrp-pipe-pct{min-width:38px;text-align:right;font-size:11px;color:var(--text-muted)}
.wrp-pipe-row.clickable{cursor:pointer;border-radius:4px;padding:5px 4px;margin:0 -4px}
.wrp-pipe-row.clickable:hover{background:var(--bg-color,#f9fafb)}
.wrp-alert{flex:1;min-width:150px;padding:12px 14px;border-radius:8px;border:1px solid;cursor:pointer;transition:box-shadow .15s,transform .1s}
.wrp-alert:hover{box-shadow:0 4px 12px rgba(0,0,0,.12);transform:translateY(-1px)}
.wrp-alert-val{font-size:20px;font-weight:700}
.wrp-alert-lbl{font-size:11px;margin-top:2px}
.red{background:#fef2f2;border-color:#fecaca;color:#991b1b}.red .wrp-alert-val{color:#dc2626}
.orange{background:#fffbeb;border-color:#fde68a;color:#92400e}.orange .wrp-alert-val{color:#d97706}
.blue{background:#eff6ff;border-color:#bfdbfe;color:#1e40af}.blue .wrp-alert-val{color:#2563eb}
.wrp-panel-overlay{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9999;display:none;align-items:center;justify-content:center}
.wrp-panel-overlay.open{display:flex}
.wrp-panel{width:min(720px,94vw);max-height:85vh;background:var(--card-bg,#fff);border-radius:12px;box-shadow:0 24px 60px rgba(0,0,0,.35);display:flex;flex-direction:column;opacity:0;transform:scale(.96) translateY(8px);transition:opacity .2s ease,transform .2s ease}
.wrp-panel.open{opacity:1;transform:scale(1) translateY(0)}
.wrp-panel-head{display:flex;align-items:center;gap:8px;padding:14px 18px;border-bottom:1px solid var(--border-color);flex-shrink:0}
.wrp-panel-head button.back{background:none;border:1px solid var(--border-color);border-radius:4px;padding:3px 10px;cursor:pointer;font-size:12px}
.wrp-panel-head .title{flex:1;font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wrp-panel-head button.close{background:none;border:none;font-size:18px;cursor:pointer;color:var(--text-muted);line-height:1}
.wrp-panel-body{flex:1;overflow-y:auto;padding:14px 18px}
.wrp-breadcrumb{font-size:11px;color:var(--text-muted);margin-bottom:12px}
.wrp-breadcrumb span{cursor:pointer;color:var(--primary,#4f46e5)}
.wrp-breadcrumb span:hover{text-decoration:underline}
.wrp-table-wrap{overflow-x:auto}
table.wrp-table{width:100%;border-collapse:collapse;font-size:12px}
table.wrp-table th{background:var(--bg-color,#f9fafb);padding:7px 10px;text-align:left;font-weight:600;border-bottom:2px solid var(--border-color);white-space:nowrap}
table.wrp-table td{padding:7px 10px;border-bottom:1px solid var(--border-color,#f3f4f6);vertical-align:top}
table.wrp-table tr.drillable{cursor:pointer}
table.wrp-table tr.drillable:hover td{background:var(--bg-color,#f0f9ff)}
.wrp-badge{display:inline-block;padding:1px 6px;border-radius:10px;font-size:10px;font-weight:600}
.wrp-empty{text-align:center;padding:40px;color:var(--text-muted);font-size:13px}
.wrp-panel-loading{text-align:center;padding:60px;color:var(--text-muted)}

script:
var ROOT = null; // set inside init() after HTML is in DOM
    var PANEL_TITLES = {
      unvisited:            'Unvisited Households',
      missing_both:         'Missing Both Docs',
      missing_aadhaar:      'Missing Aadhaar',
      missing_income:       'Missing Income Cert',
      docs_ready:           'Docs Ready \u2014 CMCHIS Not Yet Applied',
      applied:              'CMCHIS Applied',
      active:               'CMCHIS Active',
      rejected:             'Rejected',
      visited_no_change_7d: 'Visited \u2014 No Change in 7 Days',
      stagnant_14d:         'Stagnant 14+ Days (2+ Visits)',
      aadhaar_internal_sla: 'Aadhaar Internal Applied \u2014 SLA Exceeded',
      aadhaar_external_sla: 'Aadhaar External Applied \u2014 SLA Exceeded',
      income_sla:           'Income Cert Applied \u2014 SLA Exceeded',
      cmchis_sla:           'CMCHIS Applied \u2014 SLA Exceeded',
      co_below_25:          'COs Below 25% Visit Target',
      co_below_50:          'COs 25\u201350% Visit Target',
      co_below_75:          'COs 50\u201375% Visit Target',
      co_low_impact:        'Low-Impact COs'
    };
    var LEVEL_LABELS = ['org','iu','street','co','hh','individual'];
    var _data = null, _filters = {}, _navStack = [], _overlayEl = null, _panelEl = null;
    // Default date range: current calendar month
    (function() {
      var now = new Date();
      var y = now.getFullYear(), m = String(now.getMonth()+1).padStart(2,'0'), d = String(now.getDate()).padStart(2,'0');
      _filters.date_from = y + '-' + m + '-01';
      _filters.date_to   = y + '-' + m + '-' + d;
    })();

    function api(method, args) {
      return new Promise(function(res, rej) {
        var t = setTimeout(function() { rej(new Error('API timeout: ' + method)); }, 20000);
        frappe.call({method: method, args: args,
          callback: function(r) { clearTimeout(t); res(r.message); },
          error:    function(e) { clearTimeout(t); rej(typeof e === 'object' ? e : new Error(String(e))); }
        });
      });
    }

    function fmt(n) {
      if (n === null || n === undefined) return '\u2014';
      return Number(n).toLocaleString();
    }
    function esc(s) {
      if (!s) return '';
      return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }
    function smallCard(val, lbl, color) {
      return '<div class="wrp-card"><div class="wrp-card-val" style="color:'+color+'">'+fmt(val)+'</div><div class="wrp-card-lbl">'+lbl+'</div></div>';
    }

    async function init() {
      ROOT = root_element.querySelector('#wrp-dash-root');
      try {
        ROOT.innerHTML = '<div class="wrp-loading"><span class="spinner-border spinner-border-sm"></span> Loading\u2026</div>';
        _data = await api('changemakers.dashboard_api.get_dashboard_overview', {filters: _filters});
        if (!_data || _data.error === 'no_access') {
          ROOT.innerHTML = '<div class="wrp-loading">No data access for your account.</div>'; return;
        }
        renderDashboard();
        buildPanel();
      } catch(err) {
        var msg = err && (err.message || err.statusCode || String(err)) || 'unknown error';
        if (ROOT) ROOT.innerHTML = '<div class="wrp-loading" style="color:red;padding:20px;white-space:pre-wrap"><b>Dashboard error</b>\n' + msg + '</div>';
        console.error('WRP Dashboard init:', err);
      }
    }

    function renderDashboard() {
      var s = _data.structure, p = _data.pipeline, a = _data.alerts, c = _data.co_performance;
      var scope = '<div class="wrp-scope"><label>Scope:</label>'
        + '<label>Org</label><select id="wrp-f-org"><option value="">All</option></select>'
        + '<label>IU</label><select id="wrp-f-iu"><option value="">All</option></select>'
        + '<label>Street</label><select id="wrp-f-st"><option value="">All</option></select>'
        + '<label>From</label><input type="date" id="wrp-f-from" value="'+_filters.date_from+'" style="font-size:12px;padding:3px 6px;border:1px solid var(--border-color);border-radius:4px;background:var(--bg-color,#fff);color:var(--text-color,#111)">'
        + '<label>To</label><input type="date" id="wrp-f-to" value="'+_filters.date_to+'" style="font-size:12px;padding:3px 6px;border:1px solid var(--border-color);border-radius:4px;background:var(--bg-color,#fff);color:var(--text-color,#111)">'
        + '<button onclick="wrpDashRefresh()">Apply</button></div>';

      var struct = '<div class="wrp-section-title">Programme Structure</div><div class="wrp-row">'
        + smallCard(s.orgs,    'Organisations',        '#4f46e5')
        + smallCard(s.ius,     'Intervention Units',   '#4f46e5')
        + smallCard(s.streets, 'Streets',              '#4f46e5')
        + smallCard(s.cos,     'Community Organisers', '#4f46e5')
        + smallCard(s.acs,     'Area Coordinators',    '#4f46e5')
        + smallCard(s.pms,     'Programme Managers',   '#4f46e5')
        + '</div>';

      var total = p.total || 1;
      var pRows = [
        {key:'unvisited',       label:'Unvisited',           color:'#6b7280', drill:'unvisited'},
        {key:'missing_both',    label:'Missing Both Docs',   color:'#f59e0b', drill:'missing_both'},
        {key:'missing_aadhaar', label:'Missing Aadhaar',     color:'#f59e0b', drill:'missing_aadhaar'},
        {key:'missing_income',  label:'Missing Income Cert', color:'#f59e0b', drill:'missing_income'},
        {key:'docs_ready',      label:'Docs Ready',          color:'#8b5cf6', drill:'docs_ready'},
        {key:'applied',         label:'CMCHIS Applied',      color:'#3b82f6', drill:'applied'},
        {key:'active',          label:'CMCHIS Active \u2605',color:'#22c55e', drill:'active'},
        {key:'rejected',        label:'Rejected',            color:'#ef4444', drill:'rejected'}
      ];
      var pipe = '<div class="wrp-section-title">Pipeline \u2014 '+fmt(p.total)+' Households</div>'
        + '<div style="padding:8px 12px;background:var(--card-bg,#fff);border:1px solid var(--border-color,#e5e7eb);border-radius:8px">';
      for (var i=0;i<pRows.length;i++) {
        var r = pRows[i], cnt = p[r.key]||0, pct = (cnt/total*100).toFixed(1);
        var cls = r.drill ? 'clickable' : '', click = r.drill ? 'onclick="wrpDrill(\''+r.drill+'\',\'org\',null,\''+esc(PANEL_TITLES[r.drill]||r.label)+'\')"' : '';
        pipe += '<div class="wrp-pipe-row '+cls+'" '+click+'>'
          + '<div class="wrp-pipe-lbl">'+r.label+'</div>'
          + '<div class="wrp-pipe-bar"><div class="wrp-pipe-fill" style="width:'+pct+'%;background:'+r.color+'"></div></div>'
          + '<div class="wrp-pipe-cnt" style="color:'+r.color+'">'+fmt(cnt)+'</div>'
          + '<div class="wrp-pipe-pct">'+pct+'%</div></div>';
      }
      pipe += '</div>';

      var alertDefs = [
        {key:'visited_no_change_7d', val:a.visited_no_change_7d, lbl:'Visited \u2014 No Change 7d',       cls:'orange'},
        {key:'stagnant_14d',         val:a.stagnant_14d,         lbl:'Stagnant 14d+ (2+ visits)',          cls:'orange'},
        {key:'aadhaar_internal_sla', val:a.aadhaar_internal_sla, lbl:'Aadhaar Internal \u2192 SLA',        cls:'red'},
        {key:'aadhaar_external_sla', val:a.aadhaar_external_sla, lbl:'Aadhaar External \u2192 SLA',        cls:'red'},
        {key:'income_sla',           val:a.income_sla,           lbl:'Income Cert \u2192 SLA',             cls:'red'},
        {key:'cmchis_sla',           val:a.cmchis_sla,           lbl:'CMCHIS Applied \u2192 SLA',          cls:'blue'}
      ];
      var alerts = '<div class="wrp-section-title">Alerts \u26a0\ufe0f</div><div class="wrp-row">';
      for (var j=0;j<alertDefs.length;j++) {
        var ac = alertDefs[j];
        alerts += '<div class="wrp-alert '+ac.cls+'" onclick="wrpDrill(\''+ac.key+'\',\'org\',null,\''+esc(PANEL_TITLES[ac.key]||ac.lbl)+'\')">'
          + '<div class="wrp-alert-val">'+fmt(ac.val)+'</div>'
          + '<div class="wrp-alert-lbl">'+ac.lbl+'</div></div>';
      }
      alerts += '</div>';

      var cc = c.counts;
      var coDefs = [
        {key:'co_below_25',  val:cc.below_25,   lbl:'COs &lt;25% target',  cls:'red'},
        {key:'co_below_50',  val:cc.below_50,   lbl:'COs 25\u201350% target', cls:'orange'},
        {key:'co_below_75',  val:cc.below_75,   lbl:'COs 50\u201375% target', cls:'orange'},
        {key:'co_low_impact',val:cc.low_impact, lbl:'Low-Impact COs',      cls:'blue'}
      ];
      var coHtml = '<div class="wrp-section-title">CO Performance</div><div class="wrp-row">';
      for (var k=0;k<coDefs.length;k++) {
        var co = coDefs[k];
        coHtml += '<div class="wrp-alert '+co.cls+'" onclick="wrpDrill(\''+co.key+'\',\'co\',null,\''+esc(PANEL_TITLES[co.key]||co.lbl)+'\')">'
          + '<div class="wrp-alert-val">'+fmt(co.val)+'</div>'
          + '<div class="wrp-alert-lbl">'+co.lbl+'</div></div>';
      }
      coHtml += '</div>';

      ROOT.innerHTML = scope + struct + pipe + alerts + coHtml;
      populateScopeOptions();
    }

    function _scopeList(doctype, opts) { return frappe.db.get_list(doctype, opts); }
    function _fillSel(id, items, field, cur) {
      var el = ROOT && ROOT.querySelector('#'+id); if (!el) return;
      el.innerHTML = '<option value="">All</option>' + items.filter(function(r){return r[field];}).map(function(r){return '<option'+(r[field]===cur?' selected':'')+'>'+esc(r[field])+'</option>';}).join('');
    }
    function populateScopeOptions() {
      var curOrg = _filters.implementing_org || '';
      var curIU  = _filters.intervention_unit || '';
      var curSt  = _filters.street || '';
      var iuOpts = {fields:['intervention_units'], group_by:'intervention_units', limit:500};
      if (curOrg) iuOpts.filters = [['implementing_org','=',curOrg]];
      var stOpts = {fields:['name'], limit:1000};
      if (curIU)      stOpts.filters = [['intervention_units','=',curIU]];
      else if (curOrg) stOpts.filters = [['implementing_org','=',curOrg]];
      Promise.all([
        _scopeList('Street List  - WRP', {fields:['implementing_org'], group_by:'implementing_org', limit:200}),
        _scopeList('Street List  - WRP', iuOpts),
        _scopeList('Street List  - WRP', stOpts)
      ]).then(function(results) {
        _fillSel('wrp-f-org', results[0], 'implementing_org', curOrg);
        _fillSel('wrp-f-iu',  results[1], 'intervention_units', curIU);
        _fillSel('wrp-f-st',  results[2], 'name', curSt);
        _attachCascade();
      }).catch(function(){});
    }
    function _attachCascade() {
      var orgEl = ROOT && ROOT.querySelector('#wrp-f-org');
      var iuEl  = ROOT && ROOT.querySelector('#wrp-f-iu');
      var stEl  = ROOT && ROOT.querySelector('#wrp-f-st');
      if (orgEl) orgEl.onchange = function() {
        var org = orgEl.value;
        var io = {fields:['intervention_units'], group_by:'intervention_units', limit:500};
        var so = {fields:['name'], limit:1000};
        if (org) { io.filters = [['implementing_org','=',org]]; so.filters = [['implementing_org','=',org]]; }
        Promise.all([_scopeList('Street List  - WRP', io), _scopeList('Street List  - WRP', so)]).then(function(r) {
          _fillSel('wrp-f-iu', r[0], 'intervention_units', '');
          _fillSel('wrp-f-st', r[1], 'name', '');
        });
      };
      if (iuEl) iuEl.onchange = function() {
        var iu = iuEl.value, org = orgEl && orgEl.value;
        var so = {fields:['name'], limit:1000};
        if (iu) so.filters = [['intervention_units','=',iu]];
        else if (org) so.filters = [['implementing_org','=',org]];
        _scopeList('Street List  - WRP', so).then(function(items) { _fillSel('wrp-f-st', items, 'name', ''); });
      };
    }

    window.wrpDashRefresh = function() {
      var org  = ROOT && ROOT.querySelector('#wrp-f-org');
      var iu   = ROOT && ROOT.querySelector('#wrp-f-iu');
      var st   = ROOT && ROOT.querySelector('#wrp-f-st');
      var from = ROOT && ROOT.querySelector('#wrp-f-from');
      var to   = ROOT && ROOT.querySelector('#wrp-f-to');
      _filters = {};
      if (org  && org.value)  _filters.implementing_org  = org.value;
      if (iu   && iu.value)   _filters.intervention_unit = iu.value;
      if (st   && st.value)   _filters.street            = st.value;
      if (from && from.value) _filters.date_from         = from.value;
      if (to   && to.value)   _filters.date_to           = to.value;
      init();
    };

    function buildPanel() {
      if (root_element.querySelector('#wrp-panel-overlay')) return;
      _overlayEl = document.createElement('div');
      _overlayEl.id = 'wrp-panel-overlay';
      _overlayEl.className = 'wrp-panel-overlay';
      _overlayEl.onclick = function(e) { if (e.target===_overlayEl) closePanel(); };
      _panelEl = document.createElement('div');
      _panelEl.className = 'wrp-panel';
      _panelEl.innerHTML = '<div class="wrp-panel-head">'
        + '<button class="back" onclick="wrpPanelBack()">\u2190 Back</button>'
        + '<div class="title" id="wrp-panel-title">Loading\u2026</div>'
        + '<button class="close" onclick="wrpPanelClose()">&times;</button></div>'
        + '<div class="wrp-panel-body" id="wrp-panel-body">'
        + '<div class="wrp-panel-loading"><span class="spinner-border spinner-border-sm"></span> Loading\u2026</div></div>';
      _overlayEl.appendChild(_panelEl);
      root_element.appendChild(_overlayEl);
    }

    function openPanel()  { _overlayEl.classList.add('open'); setTimeout(function(){_panelEl.classList.add('open');},10); }
    function closePanel() { _panelEl.classList.remove('open'); _overlayEl.classList.remove('open'); _navStack=[]; }

    window.wrpPanelClose = closePanel;
    window.wrpPanelBack  = function() { if (_navStack.length<=1){closePanel();return;} _navStack.pop(); renderPanelData(_navStack[_navStack.length-1]); };

    window.wrpDrill = async function(metric, level, parent, titleHint) {
      openPanel();
      root_element.querySelector('#wrp-panel-title').textContent = titleHint || PANEL_TITLES[metric] || metric;
      root_element.querySelector('#wrp-panel-body').innerHTML = '<div class="wrp-panel-loading"><span class="spinner-border spinner-border-sm"></span> Loading\u2026</div>';
      var result = await api('changemakers.dashboard_api.get_drilldown', {metric:metric, level:level, parent:parent||null, filters:_filters});
      var frame = {metric:metric, level:level, parent:parent, title:titleHint||PANEL_TITLES[metric]||metric, rows:result.rows||[], columns:result.columns||[]};
      _navStack.push(frame);
      renderPanelData(frame);
    };

    function renderPanelData(frame) {
      root_element.querySelector('#wrp-panel-title').textContent = frame.title;
      var body = root_element.querySelector('#wrp-panel-body');
      var crumb = '<div class="wrp-breadcrumb">';
      for (var i=0;i<_navStack.length;i++) {
        var n=_navStack[i];
        crumb += (i<_navStack.length-1) ? '<span onclick="wrpPanelJump('+i+')">'+esc(n.title)+'</span> &rsaquo; ' : '<b>'+esc(n.title)+'</b>';
      }
      crumb += '</div>';
      var rows=frame.rows, columns=frame.columns;
      if (!rows||rows.length===0){body.innerHTML=crumb+'<div class="wrp-empty">\u2713 No issues found.</div>';return;}
      var isAgg = columns.length===2 && columns[1].fieldname==='count';
      var nextLevel = LEVEL_LABELS[LEVEL_LABELS.indexOf(frame.level)+1]||null;
      var html = crumb+'<div class="wrp-table-wrap"><table class="wrp-table"><thead><tr>';
      for (var c=0;c<columns.length;c++) html += '<th>'+esc(columns[c].label)+'</th>';
      if (isAgg) html += '<th></th>';
      html += '</tr></thead><tbody>';
      for (var r=0;r<rows.length;r++) {
        var row=rows[r], drillable=isAgg&&nextLevel;
        html += '<tr class="'+(drillable?'drillable':'')+'"'+(drillable?' onclick="wrpDrillDown(\''+esc(frame.metric)+'\',\''+nextLevel+'\',\''+esc(row.name)+'\',\''+esc(frame.title+' \u203a '+row.name)+'\')"':'')+' >';
        for (var cc=0;cc<columns.length;cc++) { var val=row[columns[cc].fieldname]; html+='<td>'+esc(val===null||val===undefined?'':String(val))+'</td>'; }
        if (isAgg) html += '<td style="color:var(--primary,#4f46e5);font-size:11px">Drill \u2192</td>';
        html += '</tr>';
      }
      html += '</tbody></table></div><div style="font-size:11px;color:var(--text-muted);margin-top:10px;text-align:right">'+fmt(rows.length)+' row'+(rows.length!==1?'s':'')+'</div>';
      body.innerHTML = html;
    }

    window.wrpPanelJump = function(idx) { _navStack=_navStack.slice(0,idx+1); renderPanelData(_navStack[_navStack.length-1]); };

    window.wrpDrillDown = async function(metric, level, parent, title) {
      root_element.querySelector('#wrp-panel-body').innerHTML='<div class="wrp-panel-loading"><span class="spinner-border spinner-border-sm"></span> Loading\u2026</div>';
      var result = await api('changemakers.dashboard_api.get_drilldown',{metric:metric,level:level,parent:parent,filters:_filters});
      var frame = {metric:metric,level:level,parent:parent,title:title,rows:result.rows||[],columns:result.columns||[]};
      _navStack.push(frame);
      renderPanelData(frame);
    };

init();
